/* Generated by Trae Work */
/* 课程笔记页 · 文档式双栏布局 */
"use strict";
(function () {
  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  document.addEventListener("DOMContentLoaded", () => {
    const ND = window.NOTES_DEEP || {};
    const DEEP = window.DEEP || { syllabus: {}, notes: {} };
    const courses = SITE_DATA.zikao.courses.filter(c => c.kind === "笔试");
    const side = document.getElementById("notes-side");
    const detail = document.getElementById("notes-detail");

    /* 课程分组：有总结笔记 > 有官方大纲 > 暂无 */
    const groups = { notes: [], syllabus: [], empty: [] };
    courses.forEach(c => {
      if (ND[c.code]) groups.notes.push(c);
      else if (DEEP.syllabus[c.code]) groups.syllabus.push(c);
      else groups.empty.push(c);
    });

    const GROUP_META = [
      { key: "notes", label: "总结型笔记" },
      { key: "syllabus", label: "官方大纲骨架" },
      { key: "empty", label: "暂无资料" }
    ];

    /* ---------- 侧栏目录 ---------- */
    function stat(c) {
      const n = ND[c.code];
      if (n) {
        const pts = n.chapters.reduce((a, ch) => a + ch.points.length, 0);
        const srcs = new Set(n.chapters.flatMap(ch => ch.sources.map(s => s.url))).size;
        return `${n.chapters.length} 章 · ${pts} 条 · ${srcs} 源`;
      }
      if (DEEP.syllabus[c.code]) {
        const s = DEEP.syllabus[c.code];
        return `${s.chapters.length} 章 · 官方大纲`;
      }
      return "暂无";
    }
    side.innerHTML = GROUP_META.map(g => {
      if (!groups[g.key].length) return "";
      return `<div class="nt-group"><div class="nt-group-label">${g.label}（${groups[g.key].length}）</div>
        ${groups[g.key].map(c => `
          <a class="nt-item" href="#${c.code}" data-code="${c.code}">
            <span class="nt-item-code">${c.code}</span>
            <span class="nt-item-name">${c.name}</span>
            <span class="nt-item-stat">${stat(c)}</span>
          </a>`).join("")}</div>`;
    }).join("");

    /* ---------- 详情渲染 ---------- */
    function notesDeepHtml(c, n) {
      const total = n.chapters.reduce((a, ch) => a + ch.points.length, 0);
      const srcSet = [...new Set(n.chapters.flatMap(ch => ch.sources.map(s => s.url)))];
      return `
        <div class="nt-meta">
          <div class="nt-meta-item"><strong>${n.chapters.length}</strong> 章</div>
          <div class="nt-meta-item"><strong>${total}</strong> 条要点</div>
          <div class="nt-meta-item"><strong>${srcSet.length}</strong> 个独立来源</div>
          <div class="nt-meta-item">快照 <strong>${ND.meta.built_at}</strong></div>
          <div class="nt-meta-actions">
            <button class="nt-btn" id="nt-expand">展开全部章节</button>
          </div>        </div>
        <div class="notice ref"><strong>公开资料整理 + 知识库核对补充。</strong>每章附来源链接可核对，标"含补充"的章节由知识库按标准教材扩充。以教材与官方大纲为准。
          配套：<a href="past-papers.html">历年真题</a> · <a href="zikao.html#course-${c.code}">自考专区课程卡</a></div>
        <details class="nt-reli"><summary>来源与整理说明（整理者自评）</summary>
          <p>${esc(n.reliability)}</p></details>
        <div class="nt-chapters">${n.chapters.map(ch => {
          const srcs = ch.sources.map(s =>
            `<a href="${s.url}" target="_blank" rel="noopener">${esc(s.platform || s.url)}</a>`).join("、");
          return `<details class="nt-chap"><summary>
              <span class="nt-chap-title">${esc(ch.title)}</span>
              <span class="nt-chap-badges">${ch.kb ? `<span class="badge code">含补充</span>` : ""}<span class="nt-chap-count">${ch.points.length} 条</span></span></summary>
            ${ch.details && ch.details.length ? `<div class="dp-block"><span class="dp-label">知识点详解（${ch.details.length} 个）</span>
              <ul class="nt-details">${ch.details.map(dt => `<li><strong>${esc(dt.k)}</strong>${esc(dt.v)}</li>`).join("")}</ul></div>` : ""}
            <ol class="nt-points">${ch.points.map(p => `<li>${esc(p)}</li>`).join("")}</ol>
            ${ch.sources.length ? `<div class="nt-src">来源：${srcs}</div>` : `<div class="nt-src">本章要点由知识库按标准教材整理核对，未摘录自特定网页</div>`}</details>`;
        }).join("")}</div>`;
    }

    function syllabusHtml(c, s) {
      const ptTotal = s.chapters.reduce((n, ch) => n + ch.points.length, 0);
      return `
        <div class="nt-meta">
          <div class="nt-meta-item"><strong>${s.chapters.length}</strong> 章</div>
          <div class="nt-meta-item"><strong>${ptTotal}</strong> 条考核知识点</div>
          <div class="nt-meta-actions"><button class="nt-btn" id="nt-expand">展开全部章节</button></div>
        </div>
        <div class="notice info">本课程知识点取自<a href="${s.syllabus_url || c.syllabus_url}" target="_blank" rel="noopener">官方考试大纲 .doc 原文</a>（目的要求 / 教学内容 / 考核知识点）。
          配套：<a href="past-papers.html">历年真题</a></div>
        <div class="nt-chapters">${s.chapters.map(ch => `
          <details class="nt-chap"><summary>
              <span class="nt-chap-title">${ch.title}</span>
              <span class="nt-chap-count">${ch.points.length} 个知识点</span></summary>
            ${ch.purpose.length ? `<div class="dp-block"><span class="dp-label">目的要求</span><ul>${ch.purpose.map(t => `<li>${t}</li>`).join("")}</ul></div>` : ""}
            ${ch.sections.length ? `<div class="dp-block"><span class="dp-label">教学内容</span><ul>${ch.sections.map(t => `<li>${t}</li>`).join("")}</ul></div>` : ""}
            ${ch.points.length ? `<div class="dp-block"><span class="dp-label">考核知识点</span><ul class="nt-points plain">${ch.points.map(p => `<li>${p.text}${p.subs && p.subs.length ? `<ul class="dp-subs">${p.subs.map(t => `<li>${t}</li>`).join("")}</ul>` : ""}</li>`).join("")}</ul></div>` : ""}
          </details>`).join("")}</div>`;
    }

    function emptyHtml(c) {
      return `<div class="notice empty"><strong>暂无可收录的课程笔记。</strong>该课程既未检索到按章节组织的公开笔记，也没有官方考试大纲可作骨架；本页不以商业考点汇总或 AI 生成内容填充。可先在<a href="past-papers.html">历年真题页</a>查看该课程已收录真题，以真题反推重点。</div>`;
    }

    function render() {
      const code = location.hash.replace("#", "");
      const c = courses.find(x => x.code === code) || groups.notes[0] || groups.syllabus[0] || groups.empty[0];
      if (!c) { detail.innerHTML = ""; return; }
      let inner = `<div class="nt-head">
          <span class="cc-code">${c.code}</span>
          <h2>${c.name}</h2>
          ${c.old_code ? `<span class="nt-old">旧代码 ${c.old_code}</span>` : ""}
        </div>`;
      if (ND[c.code]) inner += notesDeepHtml(c, ND[c.code]);
      else if (DEEP.syllabus[c.code]) inner += syllabusHtml(c, DEEP.syllabus[c.code]);
      else inner += emptyHtml(c);
      detail.innerHTML = inner;

      /* 侧栏高亮 */
      side.querySelectorAll(".nt-item").forEach(el =>
        el.classList.toggle("active", el.dataset.code === c.code));

      /* 展开全部按钮 */
      const btn = document.getElementById("nt-expand");
      if (btn) btn.addEventListener("click", () => {
        const open = btn.textContent.startsWith("展开");
        detail.querySelectorAll(".nt-chap").forEach(d => { d.open = open; });
        btn.textContent = open ? "收起全部章节" : "展开全部章节";
      });

      /* KaTeX 渲染（CDN 可用时），00023 等课程含 $...$ 公式 */
      if (window.renderMathInElement) {
        try {
          renderMathInElement(detail, {
            delimiters: [{ left: "$$", right: "$$", display: true }, { left: "$", right: "$", display: false }],
            throwOnError: false
          });
        } catch (e) { /* 离线时保留原始 LaTeX 文本 */ }
      }
    }

    side.addEventListener("click", e => {
      const item = e.target.closest(".nt-item");
      if (item && window.innerWidth < 900) detail.scrollIntoView({ behavior: "smooth" });
    });
    window.addEventListener("hashchange", render);
    render();
  });
})();
